{"content":"package jpath

import (
	"encoding/json"
	"reflect"
	"testing"
)

func mustErr(t *testing.T, d any, p string) {
	t.Helper()
	got, err := Query(d, p)
	if err == nil {
		t.Errorf("path %q: expected error, got %v", p, got)
	}
	if got != nil {
		t.Errorf("path %q: expected nil result, got %v", p, got)
	}
}

func must(t *testing.T, d any, p string, want ...any) {
	t.Helper()
	got, err := Query(d, p)
	if err != nil {
		t.Fatalf("path %q: %v", p, err)
	}
	w := []any(want)
	if len(got) == 0 && len(w) == 0 {
		if got == nil {
			t.Errorf("path %q: got nil, want empty non-nil", p)
		}
		return
	}
	if !reflect.DeepEqual(got, w) {
		t.Errorf("path %q: got %v, want %v", p, got, w)
	}
}

func TestSpec(t *testing.T) {
	d := doc(t, `{"a":{"b":[1,2,{"z":9,"a":[3]}]}, "list":[{"k":1},{"k":2}], "s":null, "n":5}`)

	must(t, d, "$", d)
	must(t, d, "$.a.b", []any{[]any{1.0, 2.0, map[string]any{"z": 9.0, "a": []any{3.0}}}})
	must(t, d, "$.a.b[0]", []any{1.0})
	must(t, d, "$.a.b[-1]", []any{map[string]any{"z": 9.0, "a": []any{3.0}}})
	must(t, d, "$.a.b[-4]", []any{}) // out of range: nothing
	must(t, d, `$.["a"]["b"][2].a`, []any{[]any{3.0}})
	must(t, d, `$.["a" + "\\" ]`, []any{}) // weird key
	must(t, d, "$.list.*", []any{map[string]any{"k": 1.0}, map[string]any{"k": 2.0}})
	must(t, d, "$.list.*.k", []any{1.0, 2.0})
	must(t, d, "$.list[*]", []any{map[string]any{"k": 1.0}, map[string]any{"k": 2.0}})
	// star on object: keys ascending
	must(t, d, `$.["a"].b[2]`, []any{map[string]any{"z": 9.0, "a": []any{3.0}}})
	must(t, d, "$.a.*", []any{[]any{1.0, 2.0, map[string]any{"z": 9.0, "a": []any{3.0}}}})
	must(t, d, `$.["list"]["0"].k`, []any{1.0})

	// recursive descent
	must(t, d, "$..a", []any{
		[]any{1.0, 2.0, map[string]any{"z": 9.0, "a": []any{3.0}}}, // $a
		[]any{3.0}, // $a.b[2].a
	})
	must(t, d, "$..k", []any{1.0, 2.0})
	must(t, d, "$.list..k", []any{1.0, 2.0})
	must(t, d, "$.a..z", []any{9.0})
	must(t, d, "$.a..a", []any{[]any{3.0}}) // current node has no 'a'? it does: $a.b[2] has a -> but node $a itself: key 'b' only. $a.b[2].a matches.
	must(t, d, "$.n..n", []any{}) // n is a number: no matches, empty
	must(t, d, "$.s..a", []any{}) // nil node: nothing

	// non-applicable steps produce nothing
	must(t, d, "$.missing", []any{})
	must(t, d, "$.n.b", []any{})  // member on non-object
	must(t, d, "$.n[0]", []any{}) // index on non-array
	must(t, d, `$.n["x"]`, []any{})
	must(t, d, "$.list[5]", []any{})
	must(t, d, "$.a..list", []any{[]any{map[string]any{"k": 1.0}, map[string]any{"k": 2.0}}})
}

func TestErrors(t *testing.T) {
	d := doc(t, `{"a":1}`)
	for _, p := range []string{
		"a.b", "", "$.", "$[", "$[1", `$["x]`, "$.1abc", "$[abc]",
		"$.a.b", "$[1]x", "$.a[", "$.a[1", `$a`, "$..", "$.**", `$[12]x`, "$.a..", "$[ ]",
	} {
		mustErr(t, d, p)
	}
}
